CREATE COLUMN TABLE "TEST_AP"."OBTC" ("AbsEntry" INTEGER CS_INT DEFAULT 0 NOT NULL , "InOpCode" NVARCHAR(15) NOT NULL , "PstTrans" NVARCHAR(1) DEFAULT '1', "BPorAct" NVARCHAR(1) DEFAULT 'C', "PstMethod" NVARCHAR(1) DEFAULT 'C', "ActFee" NVARCHAR(15), "ProjFee" NVARCHAR(20), "PrftCntFee" NVARCHAR(8), "LogInstanc" INTEGER CS_INT DEFAULT 0, "UpdateDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "Descript" NVARCHAR(40), "PrftCntFe2" NVARCHAR(8), "PrftCntFe3" NVARCHAR(8), "PrftCntFe4" NVARCHAR(8), "PrftCntFe5" NVARCHAR(8), "UserSign2" SMALLINT CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBTC_CODE_NAME" ON "TEST_AP"."OBTC" ( "InOpCode" ASC )